def T(label, acc, blocks, on=0, foot=None, example=True, extra=""): return S(label, acc, blocks, TNAV, on, TS, foot, example, extra)
def M(label, acc, blocks, on=0, foot=None, example=True, extra=""): return S(label, acc, blocks, MNAV, on, "Member App", foot, example, extra)
def photos_grid(y, n=6, cols=3, h=40, labels=None):
    w = (212 - (cols - 1) * 5) / cols; s = ""
    kinds = ["room", "house", "leaf", "sun", "room", "house"]
    for i in range(n):
        x, yy = 14 + (i % cols) * (w + 5), y + (i // cols) * (h + 5); s += photo(x, yy, w, h, ACC[i % 4], kinds[i % 6], 3)
    return s
