def tiles_last(y):
    s = ""
    for i, (nm, last) in enumerate([("Furnace", "Last service Oct 2"), ("Water Heater", "Last service Jul 9"), ("AC", "Last service Jul 9"), ("Dryer Vent", "Last service Apr 3")]):
        x, yy = 14 + (i % 2) * 109, y + (i // 2) * 78; c = ACC[i]
        s += rect(x, yy, 103, 72, "#FFFFFF", LINE, 7) + rect(x + 8, yy + 8, 26, 26, c + "1F", "none", 6) + ic("home", x + 13, yy + 13, 16, c, 2) + t(x + 8, yy + 50, nm, 10, INK, "khand", 700) + t(x + 8, yy + 62, last, 7.5, MUTE)
    return s
def list_pic(y):
    s = ""
    for i, (nm, last) in enumerate([("Furnace", "Oct 2"), ("Water Heater", "Jul 9"), ("AC", "Jul 9"), ("Dryer Vent", "Apr 3")]):
        yy = y + i * 38; s += photo(14, yy, 34, 32, ACC[i], "room", 4) + t(56, yy + 14, nm, 10, INK, "khand", 700) + t(56, yy + 25, "Installed 2014", 7.5, MUTE) + t(226, yy + 19, last, 8, MUTE, "hind", 600, "end") + ln(yy + 35, 56)
    return s
